// Shim: usa scrypt de node:crypto. No es bcrypt real, pero expone la misma API async.
import crypto from 'node:crypto';
function hashSync(pw, salt) {
  return salt + ':' + crypto.scryptSync(String(pw), salt, 32).toString('hex');
}
export async function hash(pw, rounds) {
  const salt = crypto.randomBytes(8).toString('hex');
  return hashSync(pw, salt);
}
export async function compare(pw, hashed) {
  const [salt, hex] = String(hashed).split(':');
  if (!salt || !hex) return false;
  const calc = crypto.scryptSync(String(pw), salt, 32).toString('hex');
  return crypto.timingSafeEqual(Buffer.from(calc), Buffer.from(hex));
}
export default { hash, compare };
